#include <algorithm>
#include <iostream>
#include <string>
using namespace std;

typedef long long ll;

ll lomiss, miss, d, n, a[200000], ans[20], l = 0, anses[20], l2 = 0;

void write()
{
    sort(ans, ans + l);
    for (int i = 1; i < l; i++)
        if (ans[i] != ans[i - 1])
            anses[l2++] = ans[i];
    if (l)
        anses[l2++] = ans[0];

    cout << l2 << endl;
    for (int i = 0; i < l2; i++)
        cout << ans[i] << " ";
    if (l2)
        cout << endl;
}

bool check(bool k)
{
    if (k)
        for (int i = 0; i < n - 1; i++)
            if (a[i] + d != a[i + 1])
                return false;

    if (!k)
        for (int i = 0; i < n - 1; i++)
        {
            if (i == lomiss)
                if (a[i] + d != miss || miss + d != a[i + 1])
                    return false;
            if (i != lomiss)
                if (a[i] + d != a[i + 1])
                    return false;
        }

    return true;
}

void findmissing()
{
    for (int i = 0; i < n - 1; i++)
        if (a[i] + d != a[i + 1])
        {
            miss = (a[i] + a[i + 1]) / 2;
            lomiss = i;
            return;
        }
}

int main()
{
    cin >> n;
    for (int i = 0; i < n; i++)
        cin >> a[i];

    sort(a, a + n);

    if (n == 1)
    {
        cout << -1 << endl;
        return 0;
    }

    if (n == 2)
    {
        d = a[1] - a[0];
        ans[l++] = a[0] - d;
        ans[l++] = a[1] + d;
        if ((a[0] + a[1]) % 2 == 0)
            ans[l++] = (a[0] + a[1]) / 2;
        write();
        return 0;
    }

    d = min(a[1] - a[0], a[2] - a[1]);

    if (check(true))
    {
        ans[l++] = a[0] - d;
        ans[l++] = a[n - 1] + d;
    }
    else
    {
        findmissing();
        if (check(false))
            ans[l++] = miss;
    }

    write();
    return 0;
}

#include <algorithm>
#include <iostream>
#include <set>
#include <vector>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<ll> a(n);
    for (ll &x : a) cin >> x;
    sort(a.begin(), a.end());

    if (n == 1) {
        cout << -1 << '\n';
        return 0;
    }

    set<ll> answers;

    if (n == 2) {
        ll diff = a[1] - a[0];

        answers.insert(a[0] - diff);
        answers.insert(a[1] + diff);

        if (diff % 2 == 0)
            answers.insert(a[0] + diff / 2);
    } else {
        ll diff = a[1] - a[0];
        int largeGapCount = 0;
        ll missing = 0;
        bool valid = true;

        for (int i = 1; i < n; ++i) {
            ll currentDiff = a[i] - a[i - 1];

            if (currentDiff == diff)
                continue;

            if (currentDiff == 2 * diff) {
                ++largeGapCount;
                missing = a[i - 1] + diff;
            } else {
                valid = false;
                break;
            }
        }

        if (valid) {
            if (largeGapCount == 0) {
                answers.insert(a.front() - diff);
                answers.insert(a.back() + diff);
            } else if (largeGapCount == 1) {
                answers.insert(missing);
            }
        }
    }

    cout << answers.size() << '\n';
    for (ll x : answers)
        cout << x << ' ';
    if (!answers.empty())
        cout << '\n';

    return 0;
}

