#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<ll> a(n);
    for (ll &x : a)
        cin >> x;

    sort(a.begin(), a.end());

    if (n == 1) {
        cout << -1 << '\n';
        return 0;
    }

    vector<ll> answer;

    if (n == 2) {
        ll difference = a[1] - a[0];

        if (difference == 0) {
            answer.push_back(a[0]);
        } else {
            answer.push_back(a[0] - difference);
            if (difference % 2 == 0)
                answer.push_back(a[0] + difference / 2);
            answer.push_back(a[1] + difference);
        }
    } else {
        ll difference = a[1] - a[0];
        int mismatches = 0;
        int mismatchPosition = -1;

        for (int i = 1; i < n; ++i) {
            ll currentDifference = a[i] - a[i - 1];

            if (currentDifference < difference) {
                difference = currentDifference;
                mismatches = 0;
                mismatchPosition = -1;

                for (int j = 1; j <= i; ++j) {
                    if (a[j] - a[j - 1] != difference) {
                        ++mismatches;
                        mismatchPosition = j;
                    }
                }
            } else if (currentDifference != difference) {
                ++mismatches;
                mismatchPosition = i;
            }
        }

        if (mismatches == 0) {
            if (difference == 0) {
                answer.push_back(a[0]);
            } else {
                answer.push_back(a[0] - difference);
                answer.push_back(a[n - 1] + difference);
            }
        } else if (mismatches == 1 &&
                   a[mismatchPosition] - a[mismatchPosition - 1] == 2 * difference) {
            answer.push_back(a[mismatchPosition - 1] + difference);
        }
    }

    cout << answer.size() << '\n';
    for (ll x : answer)
        cout << x << ' ';
    if (!answer.empty())
        cout << '\n';

    return 0;
}

